ALTER TABLE public.cloud_deal_checklist_items DROP CONSTRAINT IF EXISTS cloud_deal_checklist_items_note_app_ck;
ALTER TABLE public.submission_checklist_items DROP CONSTRAINT IF EXISTS submission_checklist_items_attribution_v_ck;
ALTER TABLE public.submission_checklist_items DROP CONSTRAINT IF EXISTS submission_checklist_items_note_by_kind_ck;
ALTER TABLE public.submission_checklist_items DROP CONSTRAINT IF EXISTS submission_checklist_items_note_by_app_ck;
ALTER TABLE public.submission_checklist_items DROP CONSTRAINT IF EXISTS submission_checklist_items_note_by_app_kind_ck;
ALTER TABLE public.submission_checklist_items DROP CONSTRAINT IF EXISTS submission_checklist_items_note_by_note_ck;
ALTER TABLE public.submission_checklist_items DROP CONSTRAINT IF EXISTS submission_checklist_items_note_by_v_ck;
ALTER TABLE public.submission_checklist_items
  DROP COLUMN IF EXISTS note_by_app,
  DROP COLUMN IF EXISTS note_by_kind,
  DROP COLUMN IF EXISTS attribution_v;
ALTER TABLE public.cloud_deal_checklist_items
  DROP COLUMN IF EXISTS note_app,
  DROP COLUMN IF EXISTS done_app;
DELETE FROM supabase_migrations.schema_migrations WHERE version = '20261119100000';
DO $post11ar$
DECLARE v jsonb;
BEGIN
  SELECT jsonb_build_object(
    'item_md5', (SELECT md5(p.prosrc) FROM pg_proc p WHERE p.oid = to_regprocedure('public._cloud_todo_item_json(public.cloud_deal_checklist_items)')),
    'snap_md5', (SELECT md5(p.prosrc) FROM pg_proc p WHERE p.oid = to_regprocedure('public.snapshot_submission_checklists(uuid,jsonb)')),
    'snap_count', (SELECT count(*) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname = 'snapshot_submission_checklists'),
    'snap_secdef', (SELECT p.prosecdef FROM pg_proc p WHERE p.oid = to_regprocedure('public.snapshot_submission_checklists(uuid,jsonb)')),
    'snap_exec', jsonb_build_array(has_function_privilege('anon', 'public.snapshot_submission_checklists(uuid,jsonb)', 'EXECUTE'),
                                   has_function_privilege('authenticated', 'public.snapshot_submission_checklists(uuid,jsonb)', 'EXECUTE'),
                                   has_function_privilege('service_role', 'public.snapshot_submission_checklists(uuid,jsonb)', 'EXECUTE')),
    'part_app', to_regprocedure('public._cloud_todo_part_app()') IS NOT NULL,
    'trigger', EXISTS (SELECT 1 FROM pg_trigger t WHERE t.tgrelid = 'public.cloud_deal_checklist_items'::regclass AND t.tgname = 'cloud_deal_checklist_items_part_app'),
    'columns', (SELECT count(*) FROM pg_attribute a WHERE a.attrelid IN ('public.cloud_deal_checklist_items'::regclass, 'public.submission_checklist_items'::regclass)
                  AND a.attname IN ('done_app', 'note_app', 'attribution_v', 'note_by_kind', 'note_by_app') AND NOT a.attisdropped),
    'ledger', (SELECT count(*) FROM supabase_migrations.schema_migrations WHERE version = '20261119100000')) INTO v;
  IF v ->> 'item_md5' IS DISTINCT FROM 'dadfcc2f94a1bac429089ef4aa7b0d5b' OR v ->> 'snap_md5' IS DISTINCT FROM '18168cc44ba03fadbd0de896e59806ea'
     OR (v ->> 'snap_count')::int IS DISTINCT FROM 1 OR (v ->> 'snap_secdef')::boolean IS NOT FALSE
     OR v -> 'snap_exec' IS DISTINCT FROM '[false, true, true]'::jsonb OR (v ->> 'part_app')::boolean OR (v ->> 'trigger')::boolean
     OR (v ->> 'columns')::int IS DISTINCT FROM 0 OR (v ->> 'ledger')::int IS DISTINCT FROM 0 THEN
    RAISE EXCEPTION 'ROLLBACK POST-CHECK 20261119100000 FAILED, nothing changed: %', v;
  END IF;
  RAISE NOTICE 'ROLLBACK POST-CHECK 20261119100000 OK: %', v;
END
$post11ar$;
